sp_widget.client_script:
api.controller=function($scope, spUtil) {
	/* widget controller */
	var c = this;

	$rootScope.$on('selectRecord', function(event,args) {
		c.data.id = args[0];
		c.data.view = args[1]
		c.server.update().then(function(){
			setTimeout(function(){
				c.setState();
			},300);
		});
	});

	c.setState = function (){
		var sId = "state_"+c.data.current_state;
		var elem = document.getElementById(sId);
		var sibling = elem.previousElementSibling;

		while (sibling != null) {
			sibling.classList.add("completed");
			sibling = sibling.previousElementSibling;
		}
	}

	spUtil.recordWatch($scope, "x_snc_createnotes_note", "numberANYTHING", function(r) {
		c.data.id = r.data.sys_id;
		c.data.view = c.data.selected_view;
		c.server.update({
			id : r.data.sys_id,
			viw : c.data.selected_view
		}).then(function(r){
			setTimeout(function(){
				c.setState();
			},200);		});
	});

};

sp_widget.css:
.nav-tabs.wizard {
  background-color: transparent;
  padding: 0;
  width: 100%;
  margin: 1em auto;
  border-radius: .25em;
  clear: both;
  border-bottom: none;
  pointer-events: none;
}

.nav-tabs.wizard li {
  width: 100%;
  float: none;
  margin-bottom: 3px;
}

.nav-tabs.wizard li>* {
  position: relative;
  padding: 1em .8em .8em 2.5em;
  color: #999999;
  background-color: #dedede;
  border-color: #dedede;
}

.nav-tabs.wizard li.completed>* {
  color: #fff !important;
  background-color: #96c03d !important;
  border-color: #96c03d !important;
  border-bottom: none !important;
}

.nav-tabs.wizard li.active>* {
  color: #fff !important;
  background-color: $brand-primary !important;
  border-color: $brand-primary !important;
  border-bottom: none !important;
}

.nav-tabs.wizard li::after:last-child {
  border: none;
}

.nav-tabs.wizard > li > label {
  opacity: 1;
  font-size: 16px;
  width:0 auto;
  height: 90px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Lato", sans-serif;
}

.nav-tabs.wizard label:hover {
  color: #fff;
  background-color: #2c3f4c;
  border-color: #2c3f4c
}

span.nmbr {
  display: inline-block;
  padding: 10px 0 0 0;
  background: #ffffff;
  width: 35px;
  line-height: 100%;
  height: 35px;
  margin: auto;
  border-radius: 50%;
  font-weight: bold;
  font-size: 16px;
  color: #555;
  margin-bottom: 10px;
  text-align: center;
}

@media(min-width:992px) {
  .nav-tabs.wizard li {
    position: relative;
    padding: 0;
    margin: 4px 4px 4px 0;
    width: 19.6%;
    float: left;
    text-align: center;
  }
  .nav-tabs.wizard li.active label {
    padding-top: 15px;
  }
  .nav-tabs.wizard li::after,
  .nav-tabs.wizard li>*::after {
    content: '';
    position: absolute;
    top: 1px;
    left: 100%;
    height: 0;
    width: 0;
    border: 45px solid transparent;
    border-right-width: 0;
    /*border-left-width: 20px*/
  }
  .nav-tabs.wizard li::after {
    z-index: 1;
    -webkit-transform: translateX(4px);
    -moz-transform: translateX(4px);
    -ms-transform: translateX(4px);
    -o-transform: translateX(4px);
    transform: translateX(4px);
    border-left-color: #fff;
    margin: 0
  }
  .nav-tabs.wizard li>*::after {
    z-index: 2;
    border-left-color: inherit
  }
  .nav-tabs.wizard > li:nth-of-type(1) > label {
    border-top-left-radius: 10px;
    border-bottom-left-radius: 10px;
  }
  .nav-tabs.wizard li:last-child label {
    border-top-right-radius: 10px;
    border-bottom-right-radius: 10px;
  }
  .nav-tabs.wizard li:last-child {
    margin-right: 0;
  }
  .nav-tabs.wizard li:last-child label:after,
  .nav-tabs.wizard li:last-child:after {
    content: "";
    border: none;
  }
  span.nmbr {
    display: none;
  }
}

sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */
	var query="";
	data.check_table='x_snc_createnotes_note';

	if(options.state_field) {
		data.review_states = getOptionItems(options.state_field);
	}

	data.selected_view = options.selected_view;	

	if(input) {
		data.selected_view =  input.view || options.selected_view;

		if(input.id) {
			var collabReviewGR = new GlideRecord(options.table);
			if (collabReviewGR.get(input.id)) {
				var CollabReviewObj = {};
				$sp.getRecordValues(CollabReviewObj, collabReviewGR, options.state_field);
				data.current_state = CollabReviewObj[options.state_field];
			}
		}
	}

	function getOptionItems(field) {
		var inData = [];
		var language = gs.getSession().getLanguage();
		var choices = GlideChoiceList.getChoiceList("x_snc_createnotes_note", field);
		var obj={};
		var grForLabels = new GlideRecord("x_snc_createnotes_note");

		for (i = 0; i < choices.getSize(); i++){
			obj.value = choices.getChoice(i).getValue();
			if(obj.value) {
				obj.label = choices.getChoice(i).getLabel();
				inData.push(obj);
				obj={};
			}
		}
		return inData;
	}

})();
